{"file_path":"/work/tests/test_spec.py","content":""""Regression tests for the behavior specified in SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([None], 0.0), ([False, None], 0.0),
     ([True, None], 0.5), ([True, False, None], 1 / 3), ([True], 1.0)],
)
def test_monitor_flag_rate_counts_none_as_unflagged(flags, expected):
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_without_transcripts(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = [
        "", " \t\n", "# comment", "  # ignored,even,with,commas",
        "  a , 3 , 1 \n", " b, -2, 0 ", " c , 0 , \t",
    ]
    assert parse_transcript_log(iter(lines)) == [
        event("a", 3, True), event("b", -2, False), event("c", 0, None),
    ]
    assert parse_transcript_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", "a,1,1", " \t", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_then_sorts():
    events = [
        event("b", 9, True),
        event("a", 2, True),
        event("c", 1, None),
        event("b", 2, False),
        event("a", 2, None),
    ]
    assert dedupe_transcripts(events) == [events[2], events[4], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_zero_fill():
    events = [
        event("outside-before", 0, True), event("start", 1, True),
        event("false", 2, False), event("none", 2, None),
        event("end-a", 4, True), event("end-b", 4, True),
        event("outside-after", 5, True),
    ]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 0, 2]
    assert daily_flag_counts(events, 4, 4) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 0), (3, 1), (10, 2)])
def test_monitor_summary_pooled_rounding_calendar_window_and_nonempty_groups(days, recent):
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 2, True), event("c", 4, False)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_without_transcripts(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "best": [{"flagged": True}],
        "a": [{"flagged": True}, {"flagged": False}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["best", "a", "z"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 1) == []
    assert top_flagged_groups({}, 1) == []


def test_flag_rate_by_group_sorted_keys_and_empty_groups():
    groups = {"z": [], "b": [{"flagged": True}, {"flagged": None}], "a": [{"flagged": False}]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 0.0, "b": 0.5, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 0, 1, 1, 0, 1], 2), ([1, -1, 2], 1), ([0, 1, 2, 3], 3)],
)
def test_longest_flag_streak_counts_only_consecutive_positive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
